CREATE FUNCTION public.orc_pode_ler() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND public.acesso_modulo(auth.uid(),'pmo',false) AND (public.proj_gov_ou_ceo(auth.uid()) OR EXISTS(SELECT 1 FROM mt_cadeiras c WHERE c.ativo AND (c.diretor_user_id=auth.uid() OR c.id=public.mt_cadeira_do_usuario(auth.uid())))) $$;
CREATE TABLE public.orc_integracao_config(id boolean PRIMARY KEY DEFAULT true, ativo boolean NOT NULL DEFAULT false, desde timestamptz, atualizado_em timestamptz NOT NULL DEFAULT now(), atualizado_por uuid);
GRANT SELECT,INSERT,UPDATE ON public.orc_integracao_config TO authenticated; GRANT ALL ON public.orc_integracao_config TO service_role;
ALTER TABLE public.orc_integracao_config ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.orc_integracao_config FOR SELECT TO authenticated USING(public.orc_pode_ler());
CREATE POLICY editar ON public.orc_integracao_config FOR ALL TO authenticated USING(public.acesso_modulo(auth.uid(),'pmo',false) AND public.proj_gov_ou_ceo(auth.uid())) WITH CHECK(public.acesso_modulo(auth.uid(),'pmo',false) AND public.proj_gov_ou_ceo(auth.uid()));
CREATE TABLE public.orc_realizado_espelho(centro_custo text NOT NULL, competencia text NOT NULL, realizado numeric NOT NULL, orcado numeric, origem text NOT NULL DEFAULT 'api', sincronizado_em timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(centro_custo,competencia));
GRANT SELECT ON public.orc_realizado_espelho TO authenticated; GRANT ALL ON public.orc_realizado_espelho TO service_role;
ALTER TABLE public.orc_realizado_espelho ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.orc_realizado_espelho FOR SELECT TO authenticated USING(public.orc_pode_ler());
CREATE TABLE public.orc_sync_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), modo text NOT NULL, iniciado_em timestamptz NOT NULL DEFAULT now(), concluido_em timestamptz, ok boolean NOT NULL DEFAULT false, registros integer NOT NULL DEFAULT 0, mensagem text, usuario_id uuid, arquivo text);
GRANT SELECT ON public.orc_sync_log TO authenticated; GRANT ALL ON public.orc_sync_log TO service_role;
ALTER TABLE public.orc_sync_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.orc_sync_log FOR SELECT TO authenticated USING(public.orc_pode_ler() AND public.proj_gov_ou_ceo(auth.uid()));
CREATE TABLE public.orc_projeto_centros(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), projeto_id uuid NOT NULL REFERENCES public.projetos(id), centro_custo text NOT NULL, status text NOT NULL DEFAULT 'proposto', editado_por uuid, editado_em timestamptz NOT NULL DEFAULT now(), confirmado_por uuid, confirmado_em timestamptz, UNIQUE(projeto_id,centro_custo));
GRANT SELECT ON public.orc_projeto_centros TO authenticated; GRANT ALL ON public.orc_projeto_centros TO service_role;
ALTER TABLE public.orc_projeto_centros ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.orc_projeto_centros FOR SELECT TO authenticated USING(public.orc_pode_ler() AND public.portfolio_fonte_visivel('projeto',projeto_id));
CREATE UNIQUE INDEX orc_centro_unico ON public.orc_projeto_centros(centro_custo) WHERE status='confirmado';
CREATE TABLE public.orc_projeto_budget(projeto_id uuid PRIMARY KEY REFERENCES public.projetos(id), budget_liberado numeric, fonte text NOT NULL DEFAULT '', atualizado_por uuid, atualizado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orc_projeto_budget TO authenticated; GRANT ALL ON public.orc_projeto_budget TO service_role;
ALTER TABLE public.orc_projeto_budget ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.orc_projeto_budget FOR SELECT TO authenticated USING(public.orc_pode_ler() AND public.portfolio_fonte_visivel('projeto',projeto_id));
CREATE TABLE public.orc_auditoria(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entidade text NOT NULL, ref_id uuid, anterior jsonb, novo jsonb, usuario_id uuid, criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orc_auditoria TO authenticated; GRANT ALL ON public.orc_auditoria TO service_role;
ALTER TABLE public.orc_auditoria ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.orc_auditoria FOR SELECT TO authenticated USING(public.orc_pode_ler() AND public.proj_gov_ou_ceo(auth.uid()));
ALTER TABLE public.mt_indicadores ADD COLUMN meta_2030 text;
CREATE FUNCTION public.orc_meta_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.meta_2030 IS DISTINCT FROM OLD.meta_2030 AND (auth.uid() IS NULL OR NOT public.proj_gov_ou_ceo(auth.uid())) THEN RAISE EXCEPTION 'Somente Governança/CEO edita meta 2030'; END IF; RETURN NEW; END $$;
CREATE TRIGGER orc_meta_guard BEFORE UPDATE ON public.mt_indicadores FOR EACH ROW EXECUTE FUNCTION public.orc_meta_guard();
CREATE FUNCTION public.orc_meta_salvar(_id uuid,_meta text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a text; BEGIN IF NOT public.proj_gov_ou_ceo(auth.uid()) OR NOT public.acesso_modulo(auth.uid(),'pmo',false) THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT meta_2030 INTO a FROM mt_indicadores WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'KPI inexistente'; END IF; UPDATE mt_indicadores SET meta_2030=nullif(btrim(_meta),'') WHERE id=_id; INSERT INTO orc_auditoria(entidade,ref_id,anterior,novo,usuario_id) VALUES('meta_2030',_id,to_jsonb(a),to_jsonb(_meta),auth.uid()); END $$;
CREATE FUNCTION public.orc_budget_salvar(_projeto uuid,_valor numeric,_fonte text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a jsonb; BEGIN IF NOT public.orc_pode_ler() OR NOT public.proj_gov_ou_ceo(auth.uid()) OR NOT public.portfolio_fonte_visivel('projeto',_projeto) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF _valor<0 OR (_valor IS NOT NULL AND nullif(btrim(_fonte),'') IS NULL) THEN RAISE EXCEPTION 'Informe valor não negativo e fonte da aprovação'; END IF; PERFORM 1 FROM projetos WHERE id=_projeto FOR UPDATE; SELECT to_jsonb(b) INTO a FROM orc_projeto_budget b WHERE projeto_id=_projeto; INSERT INTO orc_projeto_budget(projeto_id,budget_liberado,fonte,atualizado_por) VALUES(_projeto,_valor,coalesce(_fonte,''),auth.uid()) ON CONFLICT(projeto_id) DO UPDATE SET budget_liberado=excluded.budget_liberado,fonte=excluded.fonte,atualizado_por=auth.uid(),atualizado_em=now(); INSERT INTO orc_auditoria(entidade,ref_id,anterior,novo,usuario_id) SELECT 'budget',_projeto,a,to_jsonb(b),auth.uid() FROM orc_projeto_budget b WHERE projeto_id=_projeto; END $$;
CREATE FUNCTION public.orc_centro_salvar(_projeto uuid,_centro text,_acao text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a jsonb; r uuid; BEGIN IF NOT public.orc_pode_ler() OR NOT public.portfolio_pode_editar('projeto',_projeto) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF _acao NOT IN ('propor','confirmar','remover') OR nullif(btrim(_centro),'') IS NULL THEN RAISE EXCEPTION 'Centro/ação inválido'; END IF; IF _acao='confirmar' AND NOT public.mt_is_governanca(auth.uid()) THEN RAISE EXCEPTION 'Somente Governança confirma'; END IF; PERFORM 1 FROM projetos WHERE id=_projeto FOR UPDATE; SELECT to_jsonb(c),id INTO a,r FROM orc_projeto_centros c WHERE projeto_id=_projeto AND centro_custo=btrim(_centro) FOR UPDATE; IF _acao='confirmar' AND r IS NULL THEN RAISE EXCEPTION 'Proponha a correspondência antes'; END IF; IF _acao='remover' THEN UPDATE orc_projeto_centros SET status='removido',confirmado_por=null,confirmado_em=null,editado_por=auth.uid(),editado_em=now() WHERE id=r; ELSE INSERT INTO orc_projeto_centros(projeto_id,centro_custo,status,editado_por,confirmado_por,confirmado_em) VALUES(_projeto,btrim(_centro),CASE WHEN _acao='confirmar' THEN 'confirmado' ELSE 'proposto' END,auth.uid(),CASE WHEN _acao='confirmar' THEN auth.uid() END,CASE WHEN _acao='confirmar' THEN now() END) ON CONFLICT(projeto_id,centro_custo) DO UPDATE SET status=excluded.status,editado_por=auth.uid(),editado_em=now(),confirmado_por=excluded.confirmado_por,confirmado_em=excluded.confirmado_em RETURNING id INTO r; END IF; INSERT INTO orc_auditoria(entidade,ref_id,anterior,novo,usuario_id) SELECT 'centro',r,a,to_jsonb(c),auth.uid() FROM orc_projeto_centros c WHERE id=r; END $$;
CREATE FUNCTION public.orc_importar(_itens jsonb,_arquivo text,_modo text DEFAULT 'planilha') RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e jsonb; n integer:=0; lid uuid; BEGIN IF _modo NOT IN ('api','planilha') OR jsonb_typeof(_itens)<>'array' OR jsonb_array_length(_itens)>10000 THEN RAISE EXCEPTION 'Lote inválido (máximo 10000)'; END IF; IF NOT public.orc_pode_ler() OR (_modo='planilha' AND NOT public.mt_is_governanca(auth.uid())) OR (_modo='api' AND NOT public.proj_gov_ou_ceo(auth.uid())) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF _modo='api' AND NOT EXISTS(SELECT 1 FROM orc_integracao_config WHERE ativo) THEN RAISE EXCEPTION 'Integração desligada'; END IF;
FOR e IN SELECT value FROM jsonb_array_elements(_itens) LOOP IF nullif(btrim(e->>'centro_custo'),'') IS NULL OR coalesce(e->>'competencia','') !~ '^20[0-9]{2}-(0[1-9]|1[0-2])$' OR jsonb_typeof(e->'realizado')<>'number' OR (e->>'realizado') IS NULL THEN RAISE EXCEPTION 'Linha inválida'; END IF; END LOOP;
INSERT INTO orc_sync_log(modo,ok,usuario_id,arquivo) VALUES(_modo,true,auth.uid(),left(_arquivo,255)) RETURNING id INTO lid;
FOR e IN SELECT value FROM jsonb_array_elements(_itens) LOOP INSERT INTO orc_realizado_espelho(centro_custo,competencia,realizado,orcado,origem) VALUES(btrim(e->>'centro_custo'),e->>'competencia',(e->>'realizado')::numeric,nullif(e->>'orcado','')::numeric,_modo) ON CONFLICT(centro_custo,competencia) DO UPDATE SET realizado=excluded.realizado,orcado=excluded.orcado,origem=excluded.origem,sincronizado_em=now(); n:=n+1; END LOOP; UPDATE orc_sync_log SET registros=n,concluido_em=now() WHERE id=lid; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.orc_meta_salvar(uuid,text),public.orc_budget_salvar(uuid,numeric,text),public.orc_centro_salvar(uuid,text,text),public.orc_importar(jsonb,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.orc_meta_salvar(uuid,text),public.orc_budget_salvar(uuid,numeric,text),public.orc_centro_salvar(uuid,text,text),public.orc_importar(jsonb,text,text) TO authenticated;
